-- gap bool:590:64:1, written by an automated writer
test("breakit Drive.Commands: unlocking the big button puts it back to how it was before locking", function()
	local w = T.newWorld()
	local d = T.driver(w, T.ANITA)
	T.settle(w)
	local function ser(v)
		if type(v) ~= "table" then return tostring(v) end
		local keys = {}
		for k in pairs(v) do keys[#keys + 1] = k end
		table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
		local out = {}
		for _, k in ipairs(keys) do out[#out + 1] = tostring(k) .. "=" .. ser(v[k]) end
		return "{" .. table.concat(out, ",") .. "}"
	end
	local before = ser(d.env.WuberDB)
	d:slash("/wuber drive lock")
	d:slash("/wuber drive unlock")
	eq(ser(d.env.WuberDB), before, "saved settings after unlock match those before the lock")
	T.clean(w)
end)

