-- gap drop:116:2:1, written by an automated writer
test("breakit Drive.Commands: help lists the switches in alphabetical order", function()
	local w = T.newWorld()
	local d = T.driver(w, T.ANITA)
	T.settle(w)
	d:slash("/wuber drive help")
	local rest
	for _, line in ipairs(d.chatLines or {}) do
		local r = line:match("on or off: (.*)%.$")
		if r and line:find("Switches", 1, true) then rest = r end
	end
	ok(rest ~= nil, "a switches line is shown")
	local names = {}
	for name in (rest or ""):gmatch("[^,]+") do
		names[#names + 1] = name:match("^%s*(.-)%s*$")
	end
	local sorted = true
	for i = 2, #names do
		if names[i - 1] > names[i] then sorted = false end
	end
	ok(#names > 3 and sorted, "the switch names are in alphabetical order")
	T.clean(w)
end)

