	local w = T.newWorld()
	local d = T.driver(w, T.ANA)
	T.settle(w)
	T.goOnline(d, { price = 5000 })
	w:advance(2)
	local b = d.env.WuberDriveButton
	local wdb = d.env.WuberDB
	d.env.IsShiftKeyDown = function() return true end
	d:drag(b, 60, 0)
	w:advance(0.5)
	ok(type(wdb.drive.button.pos) == "table", "the moved place is saved first")
	d:slash("/wuber drive resetpos")
	w:advance(0.5)
	eq(wdb.drive.button.pos, nil, "resetpos clears the saved place of the big button")
	T.clean(w)
end)

